SELECT Catastrophe_Name
FROM catastrophe
ORDER BY Catastrophe_Name ASC;

SELECT COUNT(*) AS claims_with_fireplace
FROM fire_claim
WHERE Fireplace ILIKE 'yes';

SELECT AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
WHERE Year_Built < 1970;

SELECT
  100.0 * SUM(CASE WHEN Loss_Ratio >= 1.0 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) AS percentage_fire_claims_loss_ratio_at_least_1
FROM fire_claim;
